#include <bits/stdc++.h>
using namespace std;

int n;
vector<long long> a;

// Number of ordered pairs (i, j) with a[i] + a[j] >= t (a sorted ascending).
long long countAtLeast(long long t) {
    long long count = 0;
    int j = n;
    for (long long v : a) {
        while (j && a[j - 1] + v >= t) j--;
        count += n - j;
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long k;
    cin >> n >> k;
    a.resize(n);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    // Largest threshold that still has at least k pairs: the k-th largest pair sum.
    long long low = 2 * a[0], high = 2 * a[n - 1] + 1;
    while (low + 1 < high) {
        long long middle = (low + high) / 2;
        if (countAtLeast(middle) >= k) low = middle;
        else high = middle;
    }
    // Sum of every pair >= low, minus the surplus copies of low; needs 128 bits (up to 8e19).
    __int128 total = 0;
    long long count = 0;
    int j = n;
    for (long long v : a) {
        while (j && a[j - 1] + v >= low) j--;
        long long c = n - j;
        count += c;
        total += (__int128)c * v + (prefix[n] - prefix[j]);
    }
    __int128 answer = total - (__int128)(count - k) * low;
    string digits;
    do {
        digits += char('0' + (int)(answer % 10));
        answer /= 10;
    } while (answer > 0);
    reverse(digits.begin(), digits.end());
