}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    // Number of ordered pairs (i, j) with a[i] + a[j] >= t (a sorted ascending).
    static long countAtLeast(long[] a, long t) {
        int n = a.length, j = n;
        long count = 0;
        for (long v : a) {
            while (j > 0 && a[j - 1] + v >= t) j--;
            count += n - j;
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
        // Largest threshold that still has at least k pairs: the k-th largest pair sum.
        long low = 2 * a[0], high = 2 * a[n - 1] + 1;
        while (low + 1 < high) {
            long middle = (low + high) / 2;
            if (countAtLeast(a, middle) >= k) low = middle;
            else high = middle;
        }
        // Sum of every pair >= low, minus the surplus copies of low; exceeds 64 bits (up to 8e19).
        BigInteger total = BigInteger.ZERO;
        long count = 0;
        int j = n;
        for (long v : a) {
            while (j > 0 && a[j - 1] + v >= low) j--;
            long c = n - j;
            count += c;
            total = total.add(BigInteger.valueOf(c * v + (prefix[n] - prefix[j])));
        }
        BigInteger surplus = BigInteger.valueOf(count - k).multiply(BigInteger.valueOf(low));
        System.out.println(total.subtract(surplus));
    }
}

package main

import (
	"fmt"
	"io"
	"math/big"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

// Number of ordered pairs (i, j) with a[i] + a[j] >= t (a sorted ascending).
func countAtLeast(a []int64, t int64) int64 {
	n := len(a)
	j := n
	var count int64
	for _, v := range a {
		for j > 0 && a[j-1]+v >= t {
			j--
		}
		count += int64(n - j)
	}
	return count
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	k := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	prefix := make([]int64, n+1)
	for i, v := range a {
		prefix[i+1] = prefix[i] + v
	}
	// Largest threshold that still has at least k pairs: the k-th largest pair sum.
	low, high := 2*a[0], 2*a[n-1]+1
	for low+1 < high {
		middle := (low + high) / 2
		if countAtLeast(a, middle) >= k {
			low = middle
		} else {
			high = middle
		}
	}
	// Sum of every pair >= low, minus the surplus copies of low; exceeds 64 bits (up to 8e19).
	total := new(big.Int)
	var count int64
	j := n
	for _, v := range a {
		for j > 0 && a[j-1]+v >= low {
			j--
		}
		c := int64(n - j)
		count += c
		total.Add(total, big.NewInt(c*v+prefix[n]-prefix[j]))
	}
	surplus := new(big.Int).Mul(big.NewInt(count-k), big.NewInt(low))
	fmt.Println(total.Sub(total, surplus).String())
}
